#!/usr/bin/env python3# -*- coding: utf-8 -*-"""RelativityVisualLab===================Modulo: minkowsky.pyDESCRIZIONE-----------Visualizzazione interattiva di un diagramma di Minkowskibidimensionale mediante Plotly + Dash.Il diagramma rappresenta:    - asse orizzontale x  -> posizione spaziale    - asse verticale ct   -> coordinata temporaleSono inoltre rappresentati:    1. cono di luce futuro    2. cono di luce passato    3. linea di universo associata ad una velocità relativa beta = v/c    4. evento A    5. evento B    6. linea che collega gli eventi A e BCONTROLLI---------Lo slider beta modifica la pendenza della linea di universo.Quattro slider indipendenti permettono di modificare:    - posizione spaziale dell'evento A    - coordinata temporale dell'evento A    - posizione spaziale dell'evento B    - coordinata temporale dell'evento BOBIETTIVO DIDATTICO-------------------Il modulo prepara il passaggio successivo:    eventi A/B        ↓    Δx e Δt        ↓    intervallo spazio-temporale        ↓    separazione di tipo tempo / luce / spazioNOTA FISICA-----------Il diagramma di Minkowski è una rappresentazione bidimensionaledello spazio-tempo. Non rappresenta direttamente tutta la geometria4D della relatività.Per semplicità didattica utilizziamo unità arbitrarie e poniamo:    c = 1In questo modo l'asse verticale viene espresso direttamentecome ct.REQUISITI---------Python 3.12numpyplotlydashESECUZIONE----------Dal terminale, dalla cartella principale del progetto:    python -m simulations.minkowskyoppure dal menu principale di RelativityVisualLab.Il browser viene aperto automaticamente su:    http://127.0.0.1:8050"""# ============================================================# LIBRERIE# ============================================================import webbrowserimport numpy as npimport plotly.graph_objects as goimport dashfrom dash import dcc, htmlfrom dash.dependencies import Input, Output# ============================================================# PARAMETRI GENERALI DEL DIAGRAMMA# ============================================================X_MIN = -10X_MAX = 10T_MIN = -10T_MAX = 10# ============================================================# FUNZIONE PRINCIPALE DI CREAZIONE DEL DIAGRAMMA# ============================================================def create_minkowski_figure(    beta,    ax,    at,    bx,    bt):    """    Crea il diagramma di Minkowski.    Parametri    ---------    beta : float        Velocità relativa normalizzata v/c.    ax : float        Posizione spaziale dell'evento A.    at : float        Coordinata temporale dell'evento A.    bx : float        Posizione spaziale dell'evento B.    bt : float        Coordinata temporale dell'evento B.    Restituisce    -----------    go.Figure        Figura Plotly aggiornata.    """    # --------------------------------------------------------    # FIGURA    # --------------------------------------------------------    fig = go.Figure()    # ========================================================    # CONO DI LUCE FUTURO    # ========================================================    future_x = np.array([        0,        T_MAX,        0    ])    future_t = np.array([        0,        T_MAX,        T_MAX    ])    fig.add_trace(        go.Scatter(            x=future_x,            y=future_t,            mode="lines",            fill="toself",            fillcolor="rgba(255, 200, 0, 0.12)",            line=dict(                width=1,                dash="dot"            ),            name="Futuro"        )    )    # ========================================================    # CONO DI LUCE PASSATO    # ========================================================    past_x = np.array([        0,        -T_MIN,        T_MIN    ])    past_t = np.array([        0,        T_MIN,        T_MIN    ])    fig.add_trace(        go.Scatter(            x=past_x,            y=past_t,            mode="lines",            fill="toself",            fillcolor="rgba(100, 180, 255, 0.12)",            line=dict(                width=1,                dash="dot"            ),            name="Passato"        )    )    # ========================================================    # BORDI DEL CONO DI LUCE    # ========================================================    light_t = np.linspace(T_MIN, T_MAX, 300)    fig.add_trace(        go.Scatter(            x=light_t,            y=light_t,            mode="lines",            line=dict(                width=2,                dash="dash"            ),            name="c - luce"        )    )    fig.add_trace(        go.Scatter(            x=-light_t,            y=light_t,            mode="lines",            line=dict(                width=2,                dash="dash"            ),            name="c - luce"        )    )    # ========================================================    # LINEA DI UNIVERSO    # ========================================================    # beta = v/c    #    # Nel diagramma x - ct:    #    #       x = beta * ct    #    # quindi:    #    #       ct = x / beta    #    # Per beta vicino a zero evitiamo divisioni problematiche.    if abs(beta) < 0.001:        worldline_x = np.zeros(200)        worldline_t = np.linspace(            T_MIN,            T_MAX,            200        )    else:        worldline_t = np.linspace(            T_MIN,            T_MAX,            200        )        worldline_x = beta * worldline_t    # Manteniamo soltanto la parte dentro il grafico.    mask = (        (worldline_x >= X_MIN)        & (worldline_x <= X_MAX)    )    fig.add_trace(        go.Scatter(            x=worldline_x[mask],            y=worldline_t[mask],            mode="lines",            line=dict(                width=4            ),            name=f"Linea di universo β={beta:.2f}"        )    )    # ========================================================    # EVENTO A    # ========================================================    fig.add_trace(        go.Scatter(            x=[ax],            y=[at],            mode="markers+text",            marker=dict(                size=13            ),            text=[                f"A ({ax:.1f}, {at:.1f})"            ],            textposition="top right",            name="Evento A"        )    )    # ========================================================    # EVENTO B    # ========================================================    fig.add_trace(        go.Scatter(            x=[bx],            y=[bt],            mode="markers+text",            marker=dict(                size=13            ),            text=[                f"B ({bx:.1f}, {bt:.1f})"            ],            textposition="top right",            name="Evento B"        )    )    # ========================================================    # COLLEGAMENTO TRA A E B    # ========================================================    fig.add_trace(        go.Scatter(            x=[ax, bx],            y=[at, bt],            mode="lines",            line=dict(                width=3,                dash="dot"            ),            name="Intervallo A → B"        )    )    # ========================================================    # CALCOLO DIFFERENZE A/B    # ========================================================    delta_x = bx - ax    delta_t = bt - at    interval = (        delta_t ** 2        - delta_x ** 2    )    # ========================================================    # CLASSIFICAZIONE DELL'INTERVALLO    # ========================================================    tolerance = 0.05    if abs(interval) < tolerance:        interval_type = "TIPO LUCE"    elif interval > 0:        interval_type = "TIPO TEMPO"    else:        interval_type = "TIPO SPAZIO"    # ========================================================    # TESTO INFORMATIVO    # ========================================================    information = (        f"Evento A: x={ax:.2f}, ct={at:.2f}<br>"        f"Evento B: x={bx:.2f}, ct={bt:.2f}<br>"        f"Δx = {delta_x:.2f}<br>"        f"Δt = {delta_t:.2f}<br>"        f"Δs² = {interval:.2f}<br>"        f"<b>{interval_type}</b>"    )    fig.add_annotation(        x=0.98,        y=0.97,        xref="paper",        yref="paper",        text=information,        showarrow=False,        align="right",        bgcolor="rgba(255,255,255,0.85)",        borderwidth=1    )    # ========================================================    # ETICHETTE PASSATO / FUTURO    # ========================================================    fig.add_annotation(        x=0,        y=8.5,        text="FUTURO",        showarrow=False,        font=dict(            size=12        )    )    fig.add_annotation(        x=0,        y=-8.5,        text="PASSATO",        showarrow=False,        font=dict(            size=12        )    )    # ========================================================    # LAYOUT    # ========================================================    fig.update_layout(        title=(            "Diagramma di Minkowski — "            "Spazio-tempo"        ),        xaxis=dict(            title="Spazio x",            range=[                X_MIN,                X_MAX            ],            zeroline=True,            showgrid=True        ),        yaxis=dict(            title="Tempo ct",            range=[                T_MIN,                T_MAX            ],            zeroline=True,            showgrid=True,            scaleanchor="x",            scaleratio=1        ),        legend=dict(            orientation="h",            yanchor="bottom",            y=1.01,            xanchor="center",            x=0.5        ),        margin=dict(            l=45,            r=25,            t=75,            b=35        ),        height=650    )    return fig# ============================================================# APPLICAZIONE DASH# ============================================================app = dash.Dash(__name__)# ============================================================# LAYOUT DASH# ============================================================app.layout = html.Div(    [        # ----------------------------------------------------        # TITOLO        # ----------------------------------------------------        html.H2(            "Diagramma di Minkowski",            style={                "textAlign": "center",                "margin": "4px 0"            }        ),        html.Div(            "Spazio-tempo • eventi A/B • cono di luce",            style={                "textAlign": "center",                "fontSize": "13px",                "marginBottom": "5px"            }        ),        # ====================================================        # SLIDER BETA        # ====================================================        html.Div(            [                html.Label(                    "Velocità relativa β = v/c",                    style={                        "fontWeight": "bold"                    }                ),                dcc.Slider(                    id="beta-slider",                    min=0.0,                    max=0.99,                    step=0.01,                    value=0.50,                    marks={                        0.0: "0",                        0.25: "0.25c",                        0.50: "0.50c",                        0.75: "0.75c",                        0.99: "0.99c"                    },                    tooltip={                        "placement": "bottom",                        "always_visible": True                    }                )            ],            style={                "width": "94%",                "margin": "0 auto 5px auto"            }        ),        # ====================================================        # QUATTRO SLIDER AFFIANCATI        # ====================================================        html.Div(            [                # ------------------------------------------------                # EVENTO A - POSIZIONE                # ------------------------------------------------                html.Div(                    [                        html.Label(                            "A — posizione x",                            style={                                "fontWeight": "bold",                                "fontSize": "12px"                            }                        ),                        dcc.Slider(                            id="a-x-slider",                            min=-10,                            max=10,                            step=0.1,                            value=-3,                            marks={                                -10: "-10",                                0: "0",                                10: "+10"                            },                            tooltip={                                "placement": "bottom",                                "always_visible": True                            }                        )                    ],                    style={                        "width": "23%",                        "padding": "0 8px",                        "boxSizing": "border-box"                    }                ),                # ------------------------------------------------                # EVENTO A - TEMPO                # ------------------------------------------------                html.Div(                    [                        html.Label(                            "A — tempo ct",                            style={                                "fontWeight": "bold",                                "fontSize": "12px"                            }                        ),                        dcc.Slider(                            id="a-t-slider",                            min=-10,                            max=10,                            step=0.1,                            value=3,                            marks={                                -10: "-10",                                0: "0",                                10: "+10"                            },                            tooltip={                                "placement": "bottom",                                "always_visible": True                            }                        )                    ],                    style={                        "width": "23%",                        "padding": "0 8px",                        "boxSizing": "border-box"                    }                ),                # ------------------------------------------------                # EVENTO B - POSIZIONE                # ------------------------------------------------                html.Div(                    [                        html.Label(                            "B — posizione x",                            style={                                "fontWeight": "bold",                                "fontSize": "12px"                            }                        ),                        dcc.Slider(                            id="b-x-slider",                            min=-10,                            max=10,                            step=0.1,                            value=3,                            marks={                                -10: "-10",                                0: "0",                                10: "+10"                            },                            tooltip={                                "placement": "bottom",                                "always_visible": True                            }                        )                    ],                    style={                        "width": "23%",                        "padding": "0 8px",                        "boxSizing": "border-box"                    }                ),                # ------------------------------------------------                # EVENTO B - TEMPO                # ------------------------------------------------                html.Div(                    [                        html.Label(                            "B — tempo ct",                            style={                                "fontWeight": "bold",                                "fontSize": "12px"                            }                        ),                        dcc.Slider(                            id="b-t-slider",                            min=-10,                            max=10,                            step=0.1,                            value=5,                            marks={                                -10: "-10",                                0: "0",                                10: "+10"                            },                            tooltip={                                "placement": "bottom",                                "always_visible": True                            }                        )                    ],                    style={                        "width": "23%",                        "padding": "0 8px",                        "boxSizing": "border-box"                    }                )            ],            style={                "display": "flex",                "flexDirection": "row",                "flexWrap": "nowrap",                "justifyContent": "space-between",                "alignItems": "center",                "width": "96%",                "margin": "0 auto",                "boxSizing": "border-box"            }        ),        # ====================================================        # GRAFICO        # ====================================================        dcc.Graph(            id="minkowski-graph",            style={                "height": "82vh",                "width": "100%"            }        )    ],    # ========================================================    # CONTENITORE PRINCIPALE    # ========================================================    style={        "width": "100%",        "height": "100vh",        "overflow": "hidden",        "padding": "4px",        "margin": "0",        "boxSizing": "border-box"    })# ============================================================# CALLBACK# ============================================================@app.callback(    Output(        "minkowski-graph",        "figure"    ),    [        Input(            "beta-slider",            "value"        ),        Input(            "a-x-slider",            "value"        ),        Input(            "a-t-slider",            "value"        ),        Input(            "b-x-slider",            "value"        ),        Input(            "b-t-slider",            "value"        )    ])def update_minkowski(    beta,    ax,    at,    bx,    bt):    """    Aggiorna il diagramma quando cambia    uno qualsiasi dei cinque controlli.    """    return create_minkowski_figure(        float(beta),        float(ax),        float(at),        float(bx),        float(bt)    )# ============================================================# AVVIO# ============================================================def run_app():    """    Avvia il server Dash e apre automaticamente    il browser.    """    webbrowser.open(        "http://127.0.0.1:8050"    )    app.run(        debug=False,        use_reloader=False    )# ============================================================# MAIN# ============================================================if __name__ == "__main__":    run_app()